/* @autogenerated */
package net.civeira.phylax.integrationtest.feature.oauth.flow;

import java.util.List;
import java.util.Map;

import org.jose4j.jwe.JsonWebEncryption;
import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import io.quarkus.test.junit.QuarkusTest;
import io.restassured.RestAssured;
import io.restassured.http.ContentType;
import io.restassured.response.Response;
import net.civeira.phylax.feature.oauth.tokensecurity.domain.TokenIntrospectionResult;
import net.civeira.phylax.integrationtest.feature.oauth.fixtures.ClientKeys;
import net.civeira.phylax.integrationtest.feature.oauth.fixtures.OidcTestFixtures;

/**
 * Signed and encrypted responses (J-12): ID tokens encrypted for the client (4.5), signed and
 * encrypted UserInfo (3.11, 4.5) and JWT secured authorization responses (JARM, 4.2). The test RP
 * decrypts with its private key and verifies the server signature.
 */
@QuarkusTest
class JoseResponsesFlowTest extends OidcIntegrationTestBase {

  private static final String BASE = "/oauth/openid/" + OidcTestFixtures.TENANT;

  private ClientKeys rp;

  @BeforeEach
  void registerEncryptionKey() {
    rp = ClientKeys.rsa("enc-1");
    clientStoreGateway.setJwksJson("{\"keys\":[" + rp.jwk("enc") + "]}");
  }

  private String decrypt(String jwe) throws Exception {
    JsonWebEncryption encrypted = new JsonWebEncryption();
    encrypted.setCompactSerialization(jwe);
    encrypted.setKey(rp.privateKey());
    return encrypted.getPayload();
  }

  private Response passwordGrant() {
    Response issued = client.passwordGrant(OidcTestFixtures.TENANT, OidcTestFixtures.CLIENT_ID,
        OidcTestFixtures.CLIENT_SECRET, OidcTestFixtures.USERNAME, OidcTestFixtures.PASSWORD,
        OidcTestFixtures.SCOPE);
    Assertions.assertEquals(200, issued.statusCode(), issued.getBody().asString());
    return issued;
  }

  private Response userinfo(String accessToken) {
    String jti = String.valueOf(decodeToken(accessToken).get("jti"));
    tokenLookupGateway.storeByJti(jti, TokenIntrospectionResult.builder().active(true)
        .clientId(OidcTestFixtures.CLIENT_ID).jti(jti).build());
    return RestAssured.given().auth().oauth2(accessToken).get(BASE + "/userinfo");
  }

  @Test
  void idToken_isSignedThenEncryptedForTheClient() throws Exception {
    clientStoreGateway.customize(b -> b.idTokenEncryptedResponseAlg("RSA-OAEP-256"));
    String idToken = passwordGrant().jsonPath().getString("id_token");

    Assertions.assertEquals(5, idToken.split("\\.").length, "A JWE");
    Map<String, Object> claims = decodeToken(decrypt(idToken));
    Assertions.assertEquals(OidcTestFixtures.USERNAME, claims.get("sub"));
  }

  @Test
  void idToken_forAClientWithoutEncryptionKey_isNotSentInClear() {
    clientStoreGateway.setJwksJson(null);
    clientStoreGateway.customize(b -> b.idTokenEncryptedResponseAlg("RSA-OAEP"));
    Response issued = client.passwordGrant(OidcTestFixtures.TENANT, OidcTestFixtures.CLIENT_ID,
        OidcTestFixtures.CLIENT_SECRET, OidcTestFixtures.USERNAME, OidcTestFixtures.PASSWORD,
        OidcTestFixtures.SCOPE);
    Assertions.assertNotEquals(200, issued.statusCode());
  }

  @Test
  void userinfo_signed_hasIssuerAndAudience() {
    clientStoreGateway.customize(b -> b.userinfoSignedResponseAlg("RS256"));
    Response response = userinfo(passwordGrant().jsonPath().getString("access_token"));

    Assertions.assertEquals(200, response.statusCode());
    Assertions.assertTrue(response.getContentType().startsWith("application/jwt"));
    Map<String, Object> claims = decodeToken(response.getBody().asString());
    Assertions.assertEquals(OidcTestFixtures.USERNAME, claims.get("sub"));
    Assertions.assertTrue(String.valueOf(claims.get("iss")).endsWith(BASE));
    Assertions.assertTrue(claimAsList(claims.get("aud")).contains(OidcTestFixtures.CLIENT_ID));
  }

  @Test
  void userinfo_signedAndEncrypted_isDecryptedByTheClient() throws Exception {
    clientStoreGateway.customize(
        b -> b.userinfoSignedResponseAlg("RS256").userinfoEncryptedResponseAlg("RSA-OAEP"));
    Response response = userinfo(passwordGrant().jsonPath().getString("access_token"));

    Assertions.assertEquals(200, response.statusCode());
    Map<String, Object> claims = decodeToken(decrypt(response.getBody().asString()));
    Assertions.assertEquals(OidcTestFixtures.USERNAME, claims.get("sub"));
  }

  @Test
  void userinfo_withAnUnsupportedAlgorithm_isNotServed() {
    clientStoreGateway.customize(b -> b.userinfoSignedResponseAlg("ES512"));
    Assertions.assertEquals(500,
        userinfo(passwordGrant().jsonPath().getString("access_token")).statusCode());
  }

  @Test
  void jarm_success_carriesTheCodeInASignedResponse() {
    Response login = RestAssured.given().redirects().follow(false).contentType(ContentType.URLENC)
        .queryParams(Map.of("client_id", OidcTestFixtures.CLIENT_ID, "redirect_uri",
            OidcTestFixtures.REDIRECT_URI, "response_type", "code", "scope", "openid", "state",
            OidcTestFixtures.STATE, "response_mode", "jwt"))
        .formParam("username", OidcTestFixtures.USERNAME)
        .formParam("password", OidcTestFixtures.PASSWORD).formParam("csid", OidcTestFixtures.CSID)
        .post(BASE + "/auth");

    String location = login.getHeader("Location");
    Assertions.assertTrue(location.startsWith(OidcTestFixtures.REDIRECT_URI + "?response="),
        location);
    Map<String, Object> claims = decodeToken(location.substring(location.indexOf('=') + 1));
    Assertions.assertNotNull(claims.get("code"));
    Assertions.assertEquals(OidcTestFixtures.STATE, claims.get("state"));
    Assertions.assertTrue(claimAsList(claims.get("aud")).contains(OidcTestFixtures.CLIENT_ID));
    Assertions.assertNotNull(claims.get("exp"));
  }

  @Test
  void jarm_error_isSignedToo() {
    Response silent = RestAssured.given().redirects().follow(false)
        .queryParams(Map.of("client_id", OidcTestFixtures.CLIENT_ID, "redirect_uri",
            OidcTestFixtures.REDIRECT_URI, "response_type", "code", "scope", "openid", "prompt",
            "none", "response_mode", "fragment.jwt"))
        .get(BASE + "/auth");

    String location = silent.getHeader("Location");
    Assertions.assertTrue(location.startsWith(OidcTestFixtures.REDIRECT_URI + "#response="),
        location);
    Map<String, Object> claims = decodeToken(location.substring(location.indexOf('=') + 1));
    Assertions.assertEquals("login_required", claims.get("error"));
  }

  @Test
  void discovery_announcesTheOperativeAlgorithms() {
    Response discovery = RestAssured.get(BASE + "/.well-known/openid-configuration");
    Assertions.assertTrue(discovery.jsonPath().getList("response_modes_supported")
        .containsAll(List.of("jwt", "query.jwt", "fragment.jwt", "form_post.jwt")));
    Assertions.assertEquals(List.of("RS256"),
        discovery.jsonPath().getList("authorization_signing_alg_values_supported"));
    Assertions.assertEquals(List.of("RS256"),
        discovery.jsonPath().getList("userinfo_signing_alg_values_supported"));
    Assertions.assertTrue(discovery.jsonPath().getList("id_token_encryption_alg_values_supported")
        .contains("RSA-OAEP-256"));
  }
}
